 class eventclass_carreras  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["BeforeAdd"]=true;

		$this->events["BeforeEdit"]=true;

		$this->events["BeforeDelete"]=true;




	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		// Sanitizar valores financieros a enteros puros en Guaraníes
$values["costo_matricula"]      = intval(str_replace('.', '', $values["costo_matricula"]));
$values["costo_semestre"]       = intval(str_replace('.', '', $values["costo_semestre"]));
$values["costo_derecho_examen"] = intval(str_replace('.', '', $values["costo_derecho_examen"]));
$values["cantidad_cuotas"]      = intval($values["cantidad_cuotas"]);

if ($values["cantidad_cuotas"] <= 0) {
    $values["cantidad_cuotas"] = 5;
}

if (empty(trim($values["nombre"]))) {
    $message = "El nombre de la carrera es obligatorio.";
    return false;
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record updated
function BeforeEdit(&$values, $where, &$oldvalues, &$keys, &$message, $inline, &$pageObject)
{

		$values["costo_matricula"]      = intval(str_replace('.', '', $values["costo_matricula"]));
$values["costo_semestre"]       = intval(str_replace('.', '', $values["costo_semestre"]));
$values["costo_derecho_examen"] = intval(str_replace('.', '', $values["costo_derecho_examen"]));
$values["cantidad_cuotas"]      = intval($values["cantidad_cuotas"]);

if ($values["cantidad_cuotas"] <= 0) {
    $values["cantidad_cuotas"] = 5;
}

if (empty(trim($values["nombre"]))) {
    $message = "El nombre de la carrera no puede estar vacío.";
    return false;
}

return true;
;		
} // function BeforeEdit

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$car_id = intval($deleted_values["id"]);

$rsEst = DB::Query("SELECT COUNT(*) AS total FROM estudiantes WHERE carrera_id = " . $car_id);
$rEst = $rsEst->fetchAssoc();
if (intval($rEst["total"]) > 0) {
    $message = "No se puede eliminar la carrera porque tiene " . $rEst["total"] . " estudiante(s) inscripto(s). Inactive su estado en su lugar.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



